parameters.query:
SELECT portfolio_id,messaging_tier,external_unique_24h,reserved_unique_24h,
 outstanding_attempts,conservative_headroom,reason,can_send,active_cycle_id,
 last_verified_cycle_completed_at FROM age_dispatcher.preflight_view ORDER BY portfolio_id LIMIT 200;

parameters.jsCode:
const r=$input.all().map(i=>i.json).filter(x=>x&&Object.keys(x).length);
if(r.length===0)return [{json:{mode:'READ_ONLY',result:'BLOCKED',reason:'NO_PORTFOLIO_ROWS_OR_SCHEMA_NOT_SEEDED',canSend:false}}];
if(r.some(x=>x.error))return [{json:{mode:'READ_ONLY',result:'BLOCKED',reason:'POSTGRES_SCHEMA_OR_ACCESS_ERROR',canSend:false}}];
return [{json:{checkedAt:new Date().toISOString(),mode:'READ_ONLY',result:'INVENTORY_ONLY',
 portfolios:r.map(x=>({portfolioId:x.portfolio_id,reason:x.reason,conservativeHeadroom:Number(x.conservative_headroom)||0,
  tier:x.messaging_tier,reservedUnique24h:Number(x.reserved_unique_24h)||0,outstandingAttempts:Number(x.outstanding_attempts)||0,
  activeCycleId:x.active_cycle_id,priorCompletion:x.last_verified_cycle_completed_at})),
 canSend:false,crmEventWriteAuthorized:false,note:'Database headroom alone is NOT a Meta real-time remaining limit and cannot authorize sends.'}}];
